This Terraform configuration deploys a memory-optimized PostgreSQL database on AWS using Amazon RDS. It creates:

- A dedicated VPC
- Two private subnets across separate Availability Zones
- An RDS subnet group
- A security group allowing PostgreSQL access
- A randomly generated database password
- A memory-optimized PostgreSQL RDS instance using `db.r6g.large`
- Outputs for the database endpoint, port, username, and database name

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where resources will be deployed."
  type        = string
  default     = "us-east-1"
}

